import React from "react";
import classNames from "classnames";
import Link from "next/link";

interface StoreButtonProps extends React.ComponentProps<"a"> {
  variant: "appstore" | "playstore";
}

export function StoreButton(props: StoreButtonProps) {
  const { variant, className, ...rest } = props;
  const cn = classNames(className);

  const links: { key: StoreButtonProps["variant"]; link: string }[] = [
    {
      key: "appstore",
      link: "appstorelink",
    },
    {
      key: "playstore",
      link: "playstorelink",
    },
  ];

  let item: { key: StoreButtonProps["variant"]; link: string };
  let button = PlaystoreButton;

  switch (variant) {
    case "appstore":
      item = links[0];
      button = AppstoreButton;
      break;
    case "playstore":
      item = links[1];
      button = PlaystoreButton;
      break;
  }

  return (
    <Link className={cn} {...rest} href={item.link}>
      {button}
    </Link>
  );
}

